    centers=[a+50*k for k in range(-5,16)]
    pred=[]
    for y in [30,250,470]:
        pred.append(sum(f(y-c) for c in centers))
    ss=sum((pred[i]-meas[i])**2 for i in range(3))
    if best is None or ss<best[0]: best=(ss,a,pred)
print('best offset/ss/pred', best)
PY

